import type { LotteryId } from './types';
import { choose, lotteryRule, validateBet } from './lotteries';

export const GENERATION_ALGORITHM_VERSION = 'chacha20-lexicographic-rank-v1';
export const MAX_GENERATED_BETS = 1_000;

export interface GenerateBetsInput {
  lotteryId: LotteryId;
  count: number;
  numberCount: number;
  /** 32 cryptographically generated bytes, represented by exactly 64 hexadecimal characters. */
  seed: string;
  existing?: readonly (readonly number[])[];
}

/**
 * Samples ranks uniformly without replacement, then converts ranks to sorted bets.
 * A sparse Fisher–Yates shuffle avoids retries and finishes even near exhausted capacity.
 * The seed and algorithm version reproduce the same output across browser and CLI.
 */
export function generateBets({ lotteryId, count, numberCount, seed, existing = [] }: GenerateBetsInput): number[][] {
  const rule = lotteryRule(lotteryId);
  if (!Number.isInteger(count) || count < 0 || count > MAX_GENERATED_BETS) {
    throw new Error(`Gere entre 0 e ${MAX_GENERATED_BETS} jogos por operação.`);
  }
  if (!Number.isInteger(numberCount) || numberCount < rule.minNumbers || numberCount > rule.maxNumbers) {
    throw new Error(`${rule.label} exige de ${rule.minNumbers} a ${rule.maxNumbers} dezenas.`);
  }
  if (typeof seed !== 'string' || !/^[0-9a-f]{64}$/i.test(seed)) {
    throw new Error('A geração exige uma semente de 256 bits: 64 caracteres hexadecimais.');
  }
  if (!Array.isArray(existing)) throw new Error('Informe os jogos existentes em uma lista.');
  const excludedSet = new Set<bigint>();
  for (const bet of existing) {
    const validated = validateBet(lotteryId, bet);
    if (validated.length === numberCount) excludedSet.add(rankBet(validated, rule.universeSize));
  }
  const excluded = [...excludedSet].sort((left, right) => left < right ? -1 : left > right ? 1 : 0);
  let remaining = choose(rule.universeSize, numberCount) - BigInt(excluded.length);
  if (BigInt(count) > remaining) throw new Error('Não existem combinações distintas suficientes para essa geração.');
  const random = seededWords(seed);
  const moved = new Map<bigint, bigint>();
  const result: number[][] = [];
  for (let index = 0; index < count; index++) {
    const slot = randomBelow(remaining, random);
    let rank = moved.get(slot) ?? slot;
    const last = remaining - 1n;
    if (slot !== last) moved.set(slot, moved.get(last) ?? last);
    moved.delete(last);
    remaining--;
    // Map the sampled available rank back to the full rank space.
    for (const blocked of excluded) {
      if (blocked > rank) break;
      rank++;
    }
    result.push(unrankBet(rank, rule.universeSize, numberCount));
  }
  return result;
}

function rankBet(numbers: readonly number[], universeSize: number): bigint {
  let rank = 0n;
  let previous = 0;
  for (let index = 0; index < numbers.length; index++) {
    const selected = numbers[index]!;
    for (let candidate = previous + 1; candidate < selected; candidate++) {
      rank += choose(universeSize - candidate, numbers.length - index - 1);
    }
    previous = selected;
  }
  return rank;
}

function unrankBet(rank: bigint, universeSize: number, numberCount: number): number[] {
  const numbers: number[] = [];
  let candidate = 1;
  while (numbers.length < numberCount) {
    const combinations = choose(universeSize - candidate, numberCount - numbers.length - 1);
    if (rank < combinations) numbers.push(candidate);
    else rank -= combinations;
    candidate++;
  }
  return numbers;
}

function randomBelow(bound: bigint, next: () => number): bigint {
  const bits = (bound - 1n).toString(2).length;
  const words = Math.ceil(bits / 32);
  const mask = (1n << BigInt(bits)) - 1n;
  for (;;) {
    let candidate = 0n;
    for (let word = 0; word < words; word++) candidate = (candidate << 32n) | BigInt(next());
    candidate &= mask;
    if (candidate < bound) return candidate;
  }
}

/** IETF ChaCha20 with a fixed zero nonce; each independently generated key is a seed. */
function seededWords(seed: string): () => number {
  return createSeededRandom(seed).nextWord;
}

export interface SeededRandom {
  nextWord(): number;
  getWordOffset(): number;
}
/** Constant-time block seek: resuming never replays earlier random words. */
export function createSeededRandom(seed: string, wordOffset=0): SeededRandom {
  if (typeof seed!=='string' || !/^[0-9a-f]{64}$/i.test(seed)) throw new Error('Semente inválida.');
  if (!Number.isSafeInteger(wordOffset) || wordOffset<0 || wordOffset>=0x1_0000_0000*16) throw new Error('Posição aleatória inválida.');
  const state = new Uint32Array(16);
  state.set([0x61707865, 0x3320646e, 0x79622d32, 0x6b206574]);
  for (let word = 0; word < 8; word++) {
    let value = 0;
    for (let byte = 0; byte < 4; byte++) value |= Number.parseInt(seed.slice(word * 8 + byte * 2, word * 8 + byte * 2 + 2), 16) << (byte * 8);
    state[word + 4] = value >>> 0;
  }
  let block = new Uint32Array(16);
  state[12]=Math.floor(wordOffset/16);
  let position = 16;
  let initialSkip=wordOffset%16;
  let exhausted = false;
  let offset=wordOffset;
  return {getWordOffset:()=>offset,nextWord:() => {
    if (position === 16) {
      if (exhausted) throw new Error('Limite de geração da semente atingido.');
      block = new Uint32Array(state);
      for (let round = 0; round < 10; round++) {
        quarterRound(block, 0, 4, 8, 12);
        quarterRound(block, 1, 5, 9, 13);
        quarterRound(block, 2, 6, 10, 14);
        quarterRound(block, 3, 7, 11, 15);
        quarterRound(block, 0, 5, 10, 15);
        quarterRound(block, 1, 6, 11, 12);
        quarterRound(block, 2, 7, 8, 13);
        quarterRound(block, 3, 4, 9, 14);
      }
      for (let index = 0; index < 16; index++) block[index] = (block[index]! + state[index]!) >>> 0;
      state[12] = (state[12]! + 1) >>> 0;
      exhausted = state[12] === 0;
      position = initialSkip;
      initialSkip=0;
    }
    offset++;
    return block[position++]!;
  }};
}

function quarterRound(state: Uint32Array, a: number, b: number, c: number, d: number): void {
  state[a] = (state[a]! + state[b]!) >>> 0;
  state[d] = rotate(state[d]! ^ state[a]!, 16);
  state[c] = (state[c]! + state[d]!) >>> 0;
  state[b] = rotate(state[b]! ^ state[c]!, 12);
  state[a] = (state[a]! + state[b]!) >>> 0;
  state[d] = rotate(state[d]! ^ state[a]!, 8);
  state[c] = (state[c]! + state[d]!) >>> 0;
  state[b] = rotate(state[b]! ^ state[c]!, 7);
}

function rotate(value: number, bits: number): number {
  return ((value << bits) | (value >>> (32 - bits))) >>> 0;
}
